list_aliases.code:
import (
	"fmt"
)

resp, err := client.Aliases().ListAliases(ctx, map[string]any{"limit": 20}, nil)
if err != nil {
	log.Fatal(err)
}
for _, row := range resp.Map().(map[string]any)["aliases"].([]any) {
	alias := row.(map[string]any)
	fmt.Println(alias["id"], alias["alias"])
}

